      const g = E('div', 'qb-mis-good', '✓ ' + good + ' '); g.appendChild(play(good.split(' · ')[0].replace(/^.*→\s*/, ''))); r.appendChild(g);
      r.appendChild(E('div', 'qb-mis-why', why));
